"use client"

import { useEffect, useRef, useState, useCallback } from "react"
import Image from "next/image"
import { ChevronLeft, ChevronRight, MapPin, Maximize2 } from "lucide-react"

const projects = [
  {
    title: "Residencia Mirador",
    category: "Residencial",
    location: "Lima, Peru",
    year: "2024",
    image: "/images/project-1.jpg",
    description:
      "Vivienda de lujo con diseno minimalista, piscina infinita y amplias vistas panoramicas.",
  },
  {
    title: "Oficinas Nexus",
    category: "Comercial",
    location: "Arequipa, Peru",
    year: "2023",
    image: "/images/project-2.jpg",
    description:
      "Espacio de oficinas moderno con interiores abiertos, materiales naturales e iluminacion cenital.",
  },
  {
    title: "Centro Verde",
    category: "Sostenible",
    location: "Cusco, Peru",
    year: "2024",
    image: "/images/project-3.jpg",
    description:
      "Edificio eco-amigable con fachada verde vertical, jardin en azotea y certificacion LEED.",
  },
  {
    title: "Torre Altus",
    category: "Corporativo",
    location: "Lima, Peru",
    year: "2023",
    image: "/images/project-4.jpg",
    description:
      "Complejo corporativo de diseno geometrico con fachada de vidrio y estructura de concreto.",
  },
]

export function Proyectos() {
  const sectionRef = useRef<HTMLElement>(null)
  const [isVisible, setIsVisible] = useState(false)
  const [current, setCurrent] = useState(0)
  const [isAnimating, setIsAnimating] = useState(false)

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsVisible(true)
        }
      },
      { threshold: 0.1 }
    )
    if (sectionRef.current) {
      observer.observe(sectionRef.current)
    }
    return () => observer.disconnect()
  }, [])

  const navigate = useCallback(
    (direction: "prev" | "next") => {
      if (isAnimating) return
      setIsAnimating(true)
      setCurrent((prev) =>
        direction === "next"
          ? (prev + 1) % projects.length
          : (prev - 1 + projects.length) % projects.length
      )
      setTimeout(() => setIsAnimating(false), 500)
    },
    [isAnimating]
  )

  useEffect(() => {
    const interval = setInterval(() => navigate("next"), 5000)
    return () => clearInterval(interval)
  }, [navigate])

  return (
    <section
      id="proyectos"
      ref={sectionRef}
      className="relative bg-background py-24 lg:py-32"
    >
      <div className="mx-auto max-w-7xl px-6 lg:px-8">
        {/* Section Header */}
        <div
          className={`mx-auto max-w-2xl text-center transition-all duration-700 ${
            isVisible ? "translate-y-0 opacity-100" : "translate-y-8 opacity-0"
          }`}
        >
          <span className="text-xs font-semibold uppercase tracking-[0.2em] text-primary">
            Nuestros Proyectos
          </span>
          <h2 className="mt-3 font-serif text-3xl font-bold text-foreground sm:text-4xl lg:text-5xl text-balance">
            Proyectos que definen el paisaje
          </h2>
          <p className="mt-4 text-base leading-relaxed text-muted-foreground lg:text-lg">
            Cada proyecto es una historia de innovacion, funcionalidad y estetica
            que transforma entornos y comunidades.
          </p>
        </div>

        {/* Carousel */}
        <div
          className={`mt-16 transition-all duration-700 delay-200 ${
            isVisible ? "translate-y-0 opacity-100" : "translate-y-8 opacity-0"
          }`}
        >
          <div className="relative overflow-hidden rounded-2xl">
            <div className="relative aspect-[16/9] lg:aspect-[21/9]">
              {projects.map((project, index) => (
                <div
                  key={project.title}
                  className={`absolute inset-0 transition-all duration-700 ${
                    index === current
                      ? "opacity-100 scale-100"
                      : "opacity-0 scale-105"
                  }`}
                >
                  <Image
                    src={project.image}
                    alt={project.title}
                    fill
                    className="object-cover"
                  />
                  <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-black/20 to-transparent" />

                  {/* Project Info Overlay */}
                  <div className="absolute bottom-0 left-0 right-0 p-6 sm:p-8 lg:p-12">
                    <div className="flex flex-wrap items-center gap-3 mb-3">
                      <span className="rounded-full bg-primary px-3 py-1 text-xs font-semibold text-primary-foreground">
                        {project.category}
                      </span>
                      <span className="text-sm text-white/70">{project.year}</span>
                    </div>
                    <h3 className="font-serif text-2xl font-bold text-white sm:text-3xl lg:text-4xl">
                      {project.title}
                    </h3>
                    <div className="mt-2 flex items-center gap-1 text-white/70">
                      <MapPin className="h-4 w-4" />
                      <span className="text-sm">{project.location}</span>
                    </div>
                    <p className="mt-3 max-w-lg text-sm leading-relaxed text-white/70 sm:text-base">
                      {project.description}
                    </p>
                  </div>

                  {/* Expand Icon */}
                  <button
                    className="absolute top-6 right-6 flex h-10 w-10 items-center justify-center rounded-full bg-white/10 text-white backdrop-blur-sm transition-all duration-300 hover:bg-white/20"
                    aria-label="Ver proyecto completo"
                  >
                    <Maximize2 className="h-4 w-4" />
                  </button>
                </div>
              ))}
            </div>

            {/* Navigation Arrows */}
            <button
              onClick={() => navigate("prev")}
              className="absolute left-4 top-1/2 -translate-y-1/2 flex h-10 w-10 items-center justify-center rounded-full bg-white/10 text-white backdrop-blur-sm transition-all duration-300 hover:bg-white/20 sm:h-12 sm:w-12"
              aria-label="Proyecto anterior"
            >
              <ChevronLeft className="h-5 w-5" />
            </button>
            <button
              onClick={() => navigate("next")}
              className="absolute right-4 top-1/2 -translate-y-1/2 flex h-10 w-10 items-center justify-center rounded-full bg-white/10 text-white backdrop-blur-sm transition-all duration-300 hover:bg-white/20 sm:h-12 sm:w-12"
              aria-label="Siguiente proyecto"
            >
              <ChevronRight className="h-5 w-5" />
            </button>
          </div>

          {/* Dots */}
          <div className="mt-6 flex items-center justify-center gap-2">
            {projects.map((_, index) => (
              <button
                key={index}
                onClick={() => {
                  if (!isAnimating) {
                    setIsAnimating(true)
                    setCurrent(index)
                    setTimeout(() => setIsAnimating(false), 500)
                  }
                }}
                className={`h-2 rounded-full transition-all duration-300 ${
                  index === current
                    ? "w-8 bg-primary"
                    : "w-2 bg-border hover:bg-muted-foreground"
                }`}
                aria-label={`Ver proyecto ${index + 1}`}
              />
            ))}
          </div>
        </div>

        {/* Project Thumbnails Grid */}
        <div className="mt-12 grid grid-cols-2 gap-4 lg:grid-cols-4">
          {projects.map((project, index) => (
            <button
              key={project.title}
              onClick={() => {
                if (!isAnimating) {
                  setIsAnimating(true)
                  setCurrent(index)
                  setTimeout(() => setIsAnimating(false), 500)
                }
              }}
              className={`group relative overflow-hidden rounded-xl transition-all duration-300 ${
                index === current
                  ? "ring-2 ring-primary ring-offset-2 ring-offset-background"
                  : "opacity-70 hover:opacity-100"
              }`}
            >
              <div className="relative aspect-[4/3]">
                <Image
                  src={project.image}
                  alt={project.title}
                  fill
                  className="object-cover transition-transform duration-500 group-hover:scale-110"
                />
                <div className="absolute inset-0 bg-black/30 transition-opacity duration-300 group-hover:bg-black/10" />
                <div className="absolute bottom-0 left-0 right-0 p-3">
                  <p className="text-xs font-semibold text-white truncate">
                    {project.title}
                  </p>
                </div>
              </div>
            </button>
          ))}
        </div>
      </div>
    </section>
  )
}
